        CustomDeclarationValue::GuaranteedInvalid => {
            context
                .builder
                .substitution_functions
                .remove_var(registration, name);
        },
        CustomDeclarationValue::Unparsed(unparsed_value) => {
            let unparsed_value = if animation_tainted {
                let mut value = (**unparsed_value).clone();
                value.explicitly_animation_tainted = true;
                Arc::new(value)
            } else {
                Arc::clone(unparsed_value)
            };
