        value,
        Some(PropertyIdRef::from(name)),
        &context.builder.substitution_functions,
        stylist,
        context,
        attribute_tracker,
        &mut state,
        None,
        false,
    );
    let substitution = if is_var && state.cyclic_names.contains(&name) {
        Err(())
