fn registered_default(
    &self,
    name: &Name,
    registration: &PropertyDescriptors,
    url_data: &UrlExtraData,
    stylist: &Stylist,
    context: &computed::Context,
) -> RegisteredSubstitutionDefault {
    let Some(syntax) = registration.syntax.as_ref() else {
        return RegisteredSubstitutionDefault::NotDefaulted;
    };
    if syntax.is_universal() {
        return RegisteredSubstitutionDefault::NotDefaulted;
    }
    let mut parser = Parser::new(&self.css);
    if let Ok(keyword) = parser.try_parse(CSSWideKeyword::parse) {
        return RegisteredSubstitutionDefault::Defaulted(substituted_css_wide_keyword_value(
            name,
            keyword,
            registration,
            stylist,
            context,
        ));
    }
    let taint = if self.attr_tainted {
        AttrTaint::new_fully_tainted(self.css.len())
    } else {
        AttrTaint::default()
    };
    let mut parser = Parser::new(&self.css);
    if SpecifiedRegisteredValue::parse(
        &mut parser,
        syntax,
        url_data,
        None,
        AllowComputationallyDependent::Yes,
        taint,
        Some(PropertyIdRef::from(name)),
    )
    .is_err()
    {
        RegisteredSubstitutionDefault::Defaulted(invalid_at_computed_value_time_value(
            name,
            registration,
            stylist,
            context,
        ))
    } else {
        RegisteredSubstitutionDefault::NotDefaulted
    }
}

